#!/usr/bin/env node
// Writes src/contract-v1.js from schema/methods-v1.json, the normative contract, so JavaScript
// can use it without JSON imports. `--check` fails when the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';

const schema = new URL('../schema/methods-v1.json', import.meta.url);
const target = new URL('../src/contract-v1.js', import.meta.url);
const contents = `// Generated by scripts/generate.mjs from schema/methods-v1.json; do not edit.\nexport const METHODS_V1 = ${JSON.stringify(JSON.parse(readFileSync(schema, 'utf8')))};\n`;

if (process.argv.includes('--check')) {
  const current = (() => { try { return readFileSync(target, 'utf8'); } catch { return ''; } })();
  if (current !== contents) { console.error('src/contract-v1.js is stale: run node packages/protocol/scripts/generate.mjs'); process.exit(1); }
} else {
  writeFileSync(target, contents);
}
